import{_ as t,o as e,c as a,ag as i}from"./chunks/framework.DzGOF12C.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"인간의 목표와 철학의 목적 - 인식론","slug":"인간의-목표와-철학의-목적-인식론","link":"#인간의-목표와-철학의-목적-인식론","children":[]},{"level":2,"title":"덕과 지식","slug":"덕과-지식","link":"#덕과-지식","children":[{"level":3,"title":"덕(arete)","slug":"덕-arete","link":"#덕-arete","children":[]},{"level":3,"title":"지식(앎)","slug":"지식-앎","link":"#지식-앎","children":[]},{"level":3,"title":"보편자 실재론","slug":"보편자-실재론","link":"#보편자-실재론","children":[]},{"level":3,"title":"유명론","slug":"유명론","link":"#유명론","children":[]},{"level":3,"title":"프로타고라스(상대주의) — 거인","slug":"프로타고라스-상대주의-—-거인","link":"#프로타고라스-상대주의-—-거인","children":[]}]},{"level":2,"title":"동굴의 비유","slug":"동굴의-비유","link":"#동굴의-비유","children":[]},{"level":2,"title":"상기론 — 보편자로 향하는 방법","slug":"상기론-—-보편자로-향하는-방법","link":"#상기론-—-보편자로-향하는-방법","children":[{"level":3,"title":"이원론","slug":"이원론","link":"#이원론","children":[]}]}],"relativePath":"philosophy/Epistemology/01. 플라톤.md","filePath":"philosophy/Epistemology/01. 플라톤.md"}'),o={name:"philosophy/Epistemology/01. 플라톤.md"};function r(d,l,n,h,s,u){return e(),a("div",null,[...l[0]||(l[0]=[i('<h2 id="인간의-목표와-철학의-목적-인식론" tabindex="-1">인간의 목표와 철학의 목적 - 인식론 <a class="header-anchor" href="#인간의-목표와-철학의-목적-인식론" aria-label="Permalink to &quot;인간의 목표와 철학의 목적 - 인식론&quot;">​</a></h2><ul><li>모든 인간의 목표는 인간다운 삶의 성취</li><li>철학의 목적은 인간이 인간다운 삶을 위해 덕을 갖추도록 인도하는 것</li></ul><h2 id="덕과-지식" tabindex="-1">덕과 지식 <a class="header-anchor" href="#덕과-지식" aria-label="Permalink to &quot;덕과 지식&quot;">​</a></h2><h3 id="덕-arete" tabindex="-1">덕(arete) <a class="header-anchor" href="#덕-arete" aria-label="Permalink to &quot;덕(arete)&quot;">​</a></h3><ul><li>~에 대한 탁월함</li><li>인간의 덕: 인간으로 마땅히 수행해야 하는 기능에 있어서의 탁월함</li><li>탁월함 = 유익함 = 앎</li></ul><h3 id="지식-앎" tabindex="-1">지식(앎) <a class="header-anchor" href="#지식-앎" aria-label="Permalink to &quot;지식(앎)&quot;">​</a></h3><ul><li><strong>절대적</strong>으로 확실하며 <strong>필연적으로 참</strong>인 믿음 — 영속적이고 불변하는 대상을 향함</li><li><em>윤리적 관점에서는 우연적 참도 가치를 지님</em><blockquote><p>&quot;참인 확신은 행위의 올바름과 관련해서는 앎보다 더 못한 인도자가 결코 아니네.&quot;</p></blockquote></li><li>필연적 진리는 감각이 아닌 이성의 직관이나 추리를 통해 이해됨</li><li>감각을 통해 지각되는 대상은 일시적이고 변화함 — 이로부터는 단지 의견(억견)만 얻어짐</li></ul><p>![[Analogy_of_the_Divided_Line.png]]</p><blockquote><p>&quot;있는 것에는 인식이, 있지 않은 것에는 필연적으로 무지가 상관한다.&quot;</p></blockquote><p>인식론에서 존재론으로, 인식 주체에서 인식 대상으로의 전환.</p><h3 id="보편자-실재론" tabindex="-1">보편자 실재론 <a class="header-anchor" href="#보편자-실재론" aria-label="Permalink to &quot;보편자 실재론&quot;">​</a></h3><ul><li>보편자는 비물질적이며, 독립적으로 실재함</li></ul><h3 id="유명론" tabindex="-1">유명론 <a class="header-anchor" href="#유명론" aria-label="Permalink to &quot;유명론&quot;">​</a></h3><ul><li>보편자란 개별자들의 이름뿐이다</li></ul><h3 id="프로타고라스-상대주의-—-거인" tabindex="-1">프로타고라스(상대주의) — 거인 <a class="header-anchor" href="#프로타고라스-상대주의-—-거인" aria-label="Permalink to &quot;프로타고라스(상대주의) — 거인&quot;">​</a></h3><ul><li>본능과 엮여 있어 설득력 있음</li></ul><h2 id="동굴의-비유" tabindex="-1">동굴의 비유 <a class="header-anchor" href="#동굴의-비유" aria-label="Permalink to &quot;동굴의 비유&quot;">​</a></h2><p>가시계 = 동굴 안, 가지계 = 동굴 밖.</p><p>태양에 비친 그림자를 본 이후에야 태양을 인식하게 됨. 빛이 지성적 인식을 가능하게 하는 원리로 작용함.</p><ul><li>빛 → 인식: 아우구스티누스의 조명설로 연결됨 — 신이 빛으로 어떠한 지식을 내림. 이러한 빛을 인식하기 위해 이성이 필요함</li><li>중세 이후: &quot;자연의 빛&quot; — 스스로의 인식을 통해 나아감</li></ul><table tabindex="0"><thead><tr><th></th><th>의견</th><th></th><th>지식</th><th></th></tr></thead><tbody><tr><td>이미지</td><td>감각대상</td><td></td><td>수학적 대상</td><td>이데아</td></tr><tr><td>억측</td><td>믿음/확신</td><td></td><td>추론적 사고</td><td>지성적 앎</td></tr><tr><td>동굴에 비친 그림자</td><td>동굴 속 불</td><td></td><td>밖의 인식 대상</td><td>태양</td></tr></tbody></table><p>우리는 뒤도 돌아보지 못할 만큼 묶여 있어 그림자만 바라봄. (일반적인 세계에서 바라보는 일반적인 것들은 감각대상까지만 인식하는 게 아닌가?)</p><p><strong>철학자의 과제</strong>: 태양을 지각한 이후 다른 사람들에게 알려야 함. 감각세계에 남아있던 사람들보다 오히려 (다시 동굴로 돌아왔을 때) 적응하기 힘들어할 수 있음. 이러한 철학자들은 비난과 위협의 대상이 됨 (소크라테스의 경우).</p><p><strong>선분의 비유와 동굴의 비유를 연결하기 어려운 지점</strong>: 선분의 비유는 대상에 대한 인지상태의 명확성 정도로 단계를 구분함 — 가시계는 상상/믿음, 가지계는 추론/지성으로 나뉨. 동굴의 비유에서 동굴 안 그림자를 상상에, 동굴 밖 태양을 지성에 대응시키는 것은 명확하지만, <strong>동굴 속을 비추는 불을 어디에 대응시킬지가 해석의 난제</strong>임. 불을 믿음에 대응시키면, 일상생활에서는 가시계 전체를 인식하는 데 비해 동굴 속에서는 그림자만 보게 된다는 비대칭이 생기고, 그렇다고 불을 가지계 쪽으로 해석하면 플라톤이 애초에 동굴 안을 가시계 전체로, 동굴 밖을 가지계 전체로 설정한 구도와 어긋나 보이는 문제가 생김.</p><h2 id="상기론-—-보편자로-향하는-방법" tabindex="-1">상기론 — 보편자로 향하는 방법 <a class="header-anchor" href="#상기론-—-보편자로-향하는-방법" aria-label="Permalink to &quot;상기론 — 보편자로 향하는 방법&quot;">​</a></h2><p>영혼은 육체와 결합하기 이전의 기억을 가지고 있음. 영혼은 이데아와 근본적으로 다르지 않음 (다만 영혼 자체가 이데아는 아니며, 유사한 존재로 상정 — 영혼 ≠ 보편자).</p><p><strong>문제</strong>: 영혼이 개별적 존재라면 어떻게 보편적 세계에 존재하는가? (플라톤 자신도 명확히 풀지 못한 지점)</p><ul><li>선천적으로 지식을 가지고 태어남 (본유관념에 가까움) — 노예 소년 예시. 감각지각을 통해서만 지식에 도달하는 것은 아니지만, 감각지각이 계기·촉구가 될 수는 있음</li><li>상기를 통해 보편자에 도달 → 선천적 지식을 지녔음이 드러남</li></ul><h3 id="이원론" tabindex="-1">이원론 <a class="header-anchor" href="#이원론" aria-label="Permalink to &quot;이원론&quot;">​</a></h3><ul><li>영혼과 육체를 구별 — 영혼은 영원불변하지만 육체는 끊임없이 변화 → 어떻게 상기가 가능한지에 대한 근거로 작용</li><li>신체가 소멸된 이후 영혼은 지성세계에 머물며 이데아를 인식</li><li>삶과 죽음의 반복은 영혼이 있음으로써 가능</li></ul><p>감각은 이데아에 대한 지식을 방해하는 해로운 것. 철학은 궁극적 지식에 도달하려 함.</p><blockquote><p>&quot;쾌락과 고통은 못과 같아서 영혼을 육체에 묶이게 한다.&quot;</p></blockquote><ul><li><strong>감옥의 비유</strong>(육체가 영혼을 어떻게 제한하는가): 육체로부터의 해방에 도달하도록 도와야 하며, 진정한 해방은 죽음으로 나타남. 육체에 의해 영혼이 오염될 경우 보편적 세계를 망각할 수 있음 — 철학은 육체로부터의 해방을 미리 연습하는 것과 같음</li><li><strong>말과 마부의 비유</strong></li><li><strong>배와 선원의 비유</strong> (데카르트가 비유한 플라톤의 이원론): 영혼이 없으면 육체의 움직임이 불가능</li></ul>',33)])])}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
